    fn __data14() -> Py { py_dict(vec![(py_str("london"), py_str("May, June and September: 18-22C and the long evenings. July and August are warm and crowded, and November to February is grey, wet and dark by 4.30pm.")), (py_str("edinburgh"), py_str("May, June and September: 15-20C, and daylight until nearly 11pm in June; August is the Festival and the Fringe, which is either why you go or when to avoid. November to February is dark by 4pm.")), (py_str("bath"), py_str("May to September for the baths, the crescent and the canal; April and October are quieter and still fine. December is the Christmas market, which is the busiest weekend of the year.")), (py_str("dublin"), py_str("May, June and September: 16-20C and the longest days. July and August are the driest and busiest, and November to February is wet, with dark by 4.30pm.")), (py_str("amsterdam"), py_str("April to June and September: 15-22C and the canals at their best, with the tulips at Keukenhof in late April. July and August are the busiest, and November to February is cold, wet and dark early.")), (py_str("brussels"), py_str("May, June and September: 17-22C, and the Grand Place flower carpet in mid-August every second year. July and August are warm and quiet at weekends, and winter is grey and wet.")), (py_str("paris"), py_str("April to June and September to early October: 18-24C and the parks at their best. July and August are hot and many small restaurants close, and November to February is grey and cool.")), (py_str("munich"), py_str("May to September: 20-25C, beer gardens and the Alps an hour away; late September is Oktoberfest, which doubles hotel prices. December brings the Christmas markets.")), (py_str("zurich"), py_str("May to September for the lake, the old town and the mountain railways, at 22-26C in midsummer. December to February is cold and clear, which is when the Alps look their best.")), (py_str("berlin"), py_str("May to September: 20-25C, outdoor cafes, the lakes, and the city at its most relaxed. July and August are the warmest and busiest, and November to February is grey and cold.")), (py_str("prague"), py_str("April to June and September: 15-22C and the old town before the crush. July and August are busy and 25C+, and December is cold with the Christmas markets.")), (py_str("vienna"), py_str("April to June and September: 18-24C, and the ball season runs January to March. July and August are hot and the opera houses close, and December has the markets.")), (py_str("budapest"), py_str("April to June and September: 20-26C, and the thermal baths are good in cool weather too. July and August are 30C+, and December brings the Christmas markets along the Danube.")), (py_str("krakow"), py_str("May to September: 20-25C and the main square at its best; April and October are quiet and still fine. December to February is cold with snow and a Christmas market.")), (py_str("ljubljana"), py_str("May, June and September: 20-26C, and Lake Bled is warm enough to swim from June. July and August are the busiest, and winter is cold and quiet.")), (py_str("copenhagen"), py_str("May to August: 18-22C, long days, and the harbour baths open from June. July is the busiest and the jazz festival, and November to February is dark by 4pm and cold.")), (py_str("stockholm"), py_str("May to August: 18-23C and light until late, with midsummer at the end of June. The archipelago is best from July to mid-August, and winter is dark with short days.")), (py_str("helsinki"), py_str("June to August: 18-23C with almost no night, and the archipelago ferries running. January and February are the coldest, with the best chance of snow, and December is dark.")), (py_str("tallinn"), py_str("June to August: 18-22C, the old town at its best and white nights in June. December to February is cold and snowy, and the Christmas market is one of the prettiest in Europe.")), (py_str("reykjavik"), py_str("June to August gives midnight sun, open highland roads and puffins; February and March are best for the northern lights. November is dark, wet and icy, so it is the one month I would skip.")), (py_str("oslo"), py_str("May to September: 18-23C, and the fjord islands are a ferry ride from the centre. June has the longest days, and November to February is cold and dark, with skiing an hour out of town.")), (py_str("bergen"), py_str("May to September: 15-19C and the fjord trips running, with light until late in June and July. It rains most of the year, so pack a shell whatever the month.")), (py_str("rome"), py_str("April, May, late September and October: 20-26C and the ruins walkable. July and August are 30C+ with the fountains as the only relief, and August means half the restaurants shut.")), (py_str("venice"), py_str("April, May, late September and October: 18-24C, warm, not crowded and everything open. July and August are hot and packed, and November to January brings acqua alta.")), (py_str("florence"), py_str("April to June and September to October: 20-28C and the galleries without the August crush. July and August are 30C+ and busy, and winter means cool days and short queues.")), (py_str("milan"), py_str("April to June and September: 20-27C and the aperitivo season. July and August are hot and humid and the city half empties, and January is cold with the sales on.")), (py_str("naples"), py_str("April to June and September: 22-27C, with the ferries to Capri and the Amalfi coast running. July and August are hot and busy, and November to March is quiet and wet.")), (py_str("lisbon"), py_str("May, June and September: warm and dry with fewer people. July and August are hot and busy with the tourists, and November to February is wet, though milder than the north.")), (py_str("porto"), py_str("May, June and September: 18-24C and dry, with the Douro valley at its best and the vines in leaf. July and August are warm and busy, and November to March is wet and grey.")), (py_str("valencia"), py_str("April to June and September to October: 20-26C, and the sea still swimmable in October. July and August are 30C+ and busy, and March is Las Fallas if you want the crowds.")), (py_str("granada"), py_str("April to June and September to October: 18-28C, and the Alhambra bookable without a fight. July and August are 35C+ inland, and winter is cold up at the Alhambra.")), (py_str("san sebastian"), py_str("June to September: 20-24C for the beach and the pintxos, with the film festival at the end of September. July and August are the busiest, and the rest of the year is wet.")), (py_str("barcelona"), py_str("May, June and September: 22-27C, the sea warm enough to swim and the terraces full. August is hot and packed, and November to February is cool with some rain.")), (py_str("madrid"), py_str("April, May, June and September: 20-28C and dry, with the terraces out and the Prado quiet. July and August are 35C+ and the city empties, and winter is cold and clear.")), (py_str("seville"), py_str("March to May and October: 20-28C and the orange trees in flower or in fruit, with Semana Santa and the April fair the peak. July and August are 40C+, so people live at night.")), (py_str("athens"), py_str("April, May, October and early November: 20-26C and the sites walkable. July and August are 35C+ and the Acropolis is a scramble by 10am, and the islands are at their best in June and September.")), (py_str("santorini"), py_str("May, June, September and early October: 24-27C, warm sea and no crush. July and August are 30C+ with the cruise crowds landing mid-morning, and many hotels close from November to March.")), (py_str("crete"), py_str("May, June, September and early October: 24-28C and the sea warm, and the Samaria gorge opens in May. July and August are 30C+ and busy, and winter is mild on the south coast.")), (py_str("split"), py_str("May, June, September and early October: 22-27C, with the ferries to Hvar and Brac running. July and August are the peak and the old town is packed by day, and many islands shut from October.")), (py_str("dubrovnik"), py_str("May, June, September and early October: 22-27C and the city walls walkable. July and August are the peak and the cruise ships fill the old town by 10am, and winter is quiet.")), (py_str("zadar"), py_str("May, June and September: 22-27C and the sea warm enough to swim, with the Kornati islands as a day trip. July and August are busy, and winter is quiet.")), (py_str("istanbul"), py_str("April, May, September and October: 18-25C and dry, and the Bosphorus ferries at their best. July and August are hot and humid, and December to February is cold and wet.")), (py_str("tokyo"), py_str("Late March to April for the blossom, and October to November for the autumn colour and the clearest skies. June is the rainy season, August is hot and humid, and the New Year week closes many places.")), (py_str("kyoto"), py_str("Late March to early April for the blossom, and mid-November for the maples. July and August are hot and humid, and the New Year week is the busiest of the year.")), (py_str("bangkok"), py_str("November to February: dry, warm and clear, which is why it is the season. March to May is hot and hazy, and June to October is the monsoon with short, heavy afternoon rain.")), (py_str("hanoi"), py_str("October to December: 20-26C, dry and clear. January to March is cool and damp with drizzle, and May to September is hot and wet, with the heaviest rain in July and August.")), (py_str("singapore"), py_str("Any month works: it is 30C and humid all year, with rain in short bursts. February to April is the driest, November to January the wettest, and the haze can arrive in September.")), (py_str("dubai"), py_str("November to March, when it is 20-30C and you can be outside. From June to September it is over 40C, so people live in air conditioning and the hotel prices fall.")), (py_str("marrakech"), py_str("March to May and October to November: 20-28C by day, cool at night, no extreme heat. July and August are 40C+ in the city, and the desert is cold at night all year.")), (py_str("cape town"), py_str("November to March: dry, 25-28C, the beaches and the Table Mountain cableway at their best. July and August are wet and windy, which is the whale season in Hermanus.")), (py_str("havana"), py_str("November to April: dry and 24-28C. May to October is hot and wet, and August to October is hurricane season, though the rain usually comes in short afternoon storms.")), (py_str("buenos aires"), py_str("March to May and September to November: 18-25C and the parks at their best. December to February is hot and humid and the city empties in January, and July and August are cool and damp.")), (py_str("rio de janeiro"), py_str("December to March is hot, 28-32C, and Carnival falls in February or early March. May to October is cooler and drier, and the sea is still warm in September.")), (py_str("mexico city"), py_str("March to May: dry, warm and clear, before the rains. June to October is the wet season with short afternoon storms, and December to February is dry with cold nights.")), (py_str("sydney"), py_str("September to November and March to May: 20-26C, warm without the scorch. December to February is 30C+ and the beaches are packed, and June to August is mild, with whale watching.")), (py_str("melbourne"), py_str("March to May and September to November: 18-24C, and the city is at its best in autumn. December to February is hot and changeable, and winter is cold and football.")), (py_str("delhi"), py_str("October to March: dry and cooler, 15-25C. April to June is brutally hot at 40C+, and the monsoon runs July to September with flooding in some years.")), (py_str("mumbai"), py_str("November to February: dry, 25-30C and the most comfortable. March to June is hot and humid, and the monsoon runs June to September with heavy rain.")), (py_str("new york"), py_str("May to June and September to October: mild and walkable at 20-26C. July and August are hot and humid, January and February are cold with snow, and the Christmas weeks are the most expensive of the year.")), (py_str("boston"), py_str("May, June, September and October: 18-26C, and October for the foliage. July and August are hot and humid, and January and February are cold with snow.")), (py_str("chicago"), py_str("May, June and September: 20-27C and the lakefront at its best. July and August are hot and humid, and January and February are brutal with the wind off the lake.")), (py_str("san francisco"), py_str("September and October: the warmest, clearest months at 18-24C. July and August are foggy and cool, and the rain comes November to March.")), (py_str("los angeles"), py_str("March to May and September to November: 20-26C and clear. June to August is warm but the marine layer can sit all day at the beaches, and winter is mild with the odd storm.")), (py_str("toronto"), py_str("May to June and September to October: 18-25C. July and August are hot and humid, and December to March is cold with snow."))]) }
