    fn __data15() -> Py { py_dict(vec![(py_str("iceland"), py_str("June to August gives midnight sun, open highland roads and puffins; February and March are best for the northern lights. November is dark, wet and icy, so it is the one month I would skip.")), (py_str("greece"), py_str("May, June, September and early October: warm sea, open tavernas and no crush. August is 35C and the islands are packed, and many small hotels close from November to March.")), (py_str("spain"), py_str("April to June and September to October, when it is 20-28C and the coast is quiet. July and August are 35C+ inland and busy on the coast; the north stays green and cooler in summer.")), (py_str("italy"), py_str("April, May, late September and October: warm, not crowded, everything open. July and August are hot and packed, and August in the cities means half the restaurants shut.")), (py_str("portugal"), py_str("May, June and September: warm and dry with fewer people. July and August are hot and busy on the Algarve, and the north is wet from November to February.")), (py_str("croatia"), py_str("June and September: the sea is warm and the coast is not yet rammed. July and August are the peak, and many islands shut down entirely from October.")), (py_str("turkey"), py_str("May, June and September for the coast, and April or October for Istanbul. July and August are hot and crowded, and the coast is quiet and mild in winter.")), (py_str("japan"), py_str("Late March to April for the blossom, or October to November for the autumn colour. June is the rainy season, August is hot and humid, and the New Year week is the busiest travel period of the year.")), (py_str("thailand"), py_str("November to February: dry, warm and clear. March to May is hot and hazy, and June to October is the monsoon, when the islands get rough seas and some boats stop.")), (py_str("dubai"), py_str("November to March, when it is 20-30C and you can be outside. From June to September it is over 40C, so people live in air conditioning and the hotel prices fall.")), (py_str("new york"), py_str("May to June and September to October: mild and walkable. July and August are hot and humid, January and February are cold with snow, and the Christmas weeks are the most expensive of the year.")), (py_str("norway"), py_str("June to August for the fjords, the midnight sun and the coastal ferries. The northern lights need September to March and a clear, dark sky, and much of the mountain roads close in winter.")), (py_str("scotland"), py_str("May to September for the Highlands, the islands and the long evenings. Midges are worst in July and August, and November to February has very short days.")), (py_str("morocco"), py_str("March to May and September to November: warm days, cool nights, no extreme heat. July and August are 40C+ inland, and the desert is cold at night all year.")), (py_str("mexico"), py_str("November to April is the dry season, which is why it is the busy one. May to October is hot and wet, with rain usually in short afternoon storms.")), (py_str("australia"), py_str("September to November and March to May for the south: warm, not scorching. December to February is 35C+ in Sydney and Melbourne, and the north is tropical wet season then.")), (py_str("india"), py_str("October to March for most of the country: dry and cooler. April to June is brutally hot in the north, and the monsoon runs June to September.")), (py_str("usa"), py_str("It depends where: May and September for the northeast, spring and autumn for the southwest, and June to September for the national parks and mountains. Avoid the July 4th week and Thanksgiving for flights."))]) }
