    fn __data16() -> Py { py_dict(vec![(py_str("fiumicino"), py_str("the Leonardo Express to Termini is 32 minutes and €14, or a regional train to Trastevere and the metro for less. A taxi is a flat €55 to the centre.")), (py_str("lisbon airport"), py_str("the metro (red line) into town is 20 minutes for about €2 with a Viva card; a taxi is 15-20 minutes and €15-20. Uber works too.")), (py_str("charles de gaulle"), py_str("the RER B into the centre is 35 minutes and about €11.80; a taxi is a flat €56 to the right bank. Orly has the Orlyval plus RER, and a tram now too.")), (py_str("barcelona airport"), py_str("the Aerobus to Plaza Catalunya is 35 minutes and about €7.50; the train to Sants is cheaper and slower. A taxi is a flat €35.")), (py_str("amsterdam airport"), py_str("the train to Centraal is 15-20 minutes and about €6; buy the ticket from the machine before the gates, not on board.")), (py_str("dublin airport"), py_str("the Aircoach or the 747 bus to the centre is about €7-10 and 30-45 minutes; a taxi is €25-30. There is no train link yet.")), (py_str("edinburgh airport"), py_str("the tram or the 100 bus to the centre is about 30 minutes and £6.50; a taxi is £25-30. The tram stops at Haymarket and Princes Street.")), (py_str("jfk"), py_str("the AirTrain plus the subway is about €10 and 60-75 minutes; the LIRR from Jamaica is faster. A yellow cab is a flat fare to Manhattan, plus tolls and tip.")), (py_str("berlin airport"), py_str("the FEX or S9 train to Hauptbahnhof is 30 minutes and about €4.40; a taxi is €40-50.")), (py_str("porto airport"), py_str("the metro line E to the centre is 30 minutes for about €2 with an Andante card; a taxi is 20-25 minutes and €20-25.")), (py_str("dubrovnik airport"), py_str("the Atlas shuttle to the old town is about €8 and 30-40 minutes, timed to the flights; a taxi is €40-50. There is no train.")), (py_str("krakow airport"), py_str("the train to the main station is 20 minutes for about 12 zloty, and bus 252 runs too; a taxi is 25-30 minutes and 70-90 zloty.")), (py_str("budapest airport"), py_str("bus 100E to Deak Ferenc ter is 30 minutes for about 900 forint, and no metro reaches the airport; a taxi is 25-30 minutes and about 10,000 forint.")), (py_str("venice airport"), py_str("the ATVO bus to Piazzale Roma is 20 minutes and €10, and the Alilaguna boat to San Marco is 75 minutes and €15; a water taxi is €100+.")), (py_str("copenhagen airport"), py_str("the metro to Kongens Nytorv is 15 minutes and about 30 kroner, and the train also runs to the central station; a taxi is 250-300 kroner.")), (py_str("athens airport"), py_str("metro line 3 to Syntagma is 40 minutes and €9, and the X95 bus is €5.50 and slower; a taxi is 35-45 minutes and €40.")), (py_str("seville airport"), py_str("the EA airport bus to the centre is 35 minutes and €4; a taxi is 20 minutes and about €25. There is no train link.")), (py_str("florence airport"), py_str("the T2 tram to Santa Maria Novella is 20 minutes and €1.50; a taxi is 20 minutes and about €25.")), (py_str("marrakech airport"), py_str("bus 19 to the medina is 30 minutes and 30 dirham; a taxi should be about 100 dirham, and agree the price before you get in.")), (py_str("naples airport"), py_str("the Alibus to the central station and the port is 20-25 minutes and €5; a taxi is about €25, agreed first.")), (py_str("madrid airport"), py_str("the metro line 8 to Nuevos Ministerios is about €5 and 40 minutes; the Cercanias train to Atocha is faster. A taxi is a flat €33.")), (py_str("prague airport"), py_str("bus 119 to the metro at Nadrazi Veleslavin is 15 minutes and 40 koruna, then the metro, or the Airport Express bus to the main station in about 40 minutes; a taxi is 30 minutes and 500-600 koruna, and agree the price first.")), (py_str("istanbul airport"), py_str("the metro or the Havaist bus to the centre is about €2-5 and takes 40-60 minutes; a taxi is much more and the traffic is bad.")), (py_str("lisbon"), py_str("the metro (red line) into town is 20 minutes for about €2 with a Viva card; a taxi is 15-20 minutes and €15-20.")), (py_str("rome"), py_str("from Fiumicino the Leonardo Express to Termini is 32 minutes and €14; the regional train plus metro is cheaper. A taxi is a flat €55.")), (py_str("paris"), py_str("from Charles de Gaulle the RER B is 35 minutes and about €11.80; from Orly the Orlyval plus RER, or the tram. A taxi from CDG is a flat €56 to the right bank.")), (py_str("vienna airport"), py_str("the S-Bahn S7 to Wien Mitte is 25 minutes for about €4.60, and the City Airport Train is 16 minutes and €14.90. A taxi is a flat €40.")), (py_str("zurich airport"), py_str("the train to the main station is 10 to 12 minutes for about 7 francs, and it runs every few minutes. A taxi is 30 to 40 francs and slower.")), (py_str("munich airport"), py_str("the S-Bahn S1 or S8 to the centre is 40 minutes on a normal city ticket, about €13; a taxi is €70 or more and no quicker in traffic.")), (py_str("frankfurt airport"), py_str("the S-Bahn S8 or S9 to the main station is 15 minutes and about €6.50; a taxi is 25 minutes and €35-40.")), (py_str("stockholm airport"), py_str("the Arlanda Express to the central station is 20 minutes and about 320 kronor, and the commuter train is 40 minutes and cheaper; the express is the most expensive way. A taxi is 45 minutes and 500 kronor or more.")), (py_str("oslo airport"), py_str("the Flytoget to the central station is 20 minutes for about 240 kroner, and the Vy regional train is slower and half the price. A taxi is 45 minutes and very expensive.")), (py_str("helsinki airport"), py_str("the I or P train to the central station is 30 minutes for about €4.10, and it is the same ticket as the city trams.")), (py_str("tokyo airport"), py_str("Haneda is the quick one: the monorail to Hamamatsucho is 20 minutes for about 500 yen, and the Keikyu line goes to Shinagawa. From Narita the Skyliner to Ueno is 41 minutes and about 2,570 yen.")), (py_str("kyoto"), py_str("Kansai airport is 75 minutes away on the Haruka train, which is the easiest way; a taxi is not worth the price.")), (py_str("brussels airport"), py_str("the train to the central station is 20 minutes and about €11, and it runs four times an hour. From Charleroi the bus to Midi takes an hour.")), (py_str("bangkok airport"), py_str("the Airport Rail Link from Suvarnabhumi to Phaya Thai is 30 minutes for 45 baht, and the metro joins it there. A taxi with tolls is 40 to 60 minutes and 400 to 500 baht.")), (py_str("singapore airport"), py_str("the MRT to the city is 30 to 40 minutes for about S$2, changing at Tanah Merah. A taxi is 20 to 30 minutes and S$20-30 with the airport surcharge.")), (py_str("hanoi airport"), py_str("bus 86 to the old quarter is 45 minutes for 35,000 dong, and a Grab or a taxi is about 350,000 dong and 40 minutes.")), (py_str("cape town airport"), py_str("an Uber or a taxi to the centre is 20 to 30 minutes and about 250 rand. There is a train, but not one to take with bags.")), (py_str("mexico city airport"), py_str("the metro line 5 is the cheap way and slow with luggage; a taxi from the official stand inside the terminal is 30 to 45 minutes and about 250 pesos.")), (py_str("havana airport"), py_str("a taxi to the old town is 25 to 30 minutes and about 25 dollars or the same in euros; the airport bus is not worth the wait.")), (py_str("buenos aires airport"), py_str("Ezeiza is 45 minutes by taxi and about 30 dollars, and bus 8 is the cheap way but slow. Aeroparque is in the city itself.")), (py_str("rio airport"), py_str("Galeao is 30 to 50 minutes by taxi, and the BRT bus to the centre is cheaper and takes about an hour. Santos Dumont is in the city.")), (py_str("sydney airport"), py_str("the Airport Link train to Central is 13 minutes for about 20 Australian dollars. A taxi is 25 to 35 dollars and slower in the morning peak.")), (py_str("toronto airport"), py_str("the UP Express to Union station is 25 minutes for about 12 Canadian dollars and runs every 15 minutes.")), (py_str("chicago airport"), py_str("the CTA Blue Line from O'Hare runs all night, 45 minutes for $5. A taxi is 40 to 60 minutes and $50 or more with the tip.")), (py_str("boston airport"), py_str("the Silver Line SL1 bus from the terminals takes about 20 minutes for a normal subway fare, and the water taxi across the harbour is the fun way.")), (py_str("san francisco airport"), py_str("BART to the city is 30 minutes for about $10. A taxi is 25 to 40 minutes and $50 or more.")), (py_str("los angeles airport"), py_str("the FlyAway bus to Union Station is about 45 minutes and $10; a taxi or a rideshare is 30 to 60 minutes and $50 or more, depending on the traffic."))]) }
