    fn __data17() -> Py { py_dict(vec![(py_str("dubrovnik"), py_str("Dubrovnik (DBV) is 20km south-east, and the Atlas shuttle to the old town is about €8 and 30-40 minutes, timed to the flights; a taxi is €40-50.")), (py_str("krakow"), py_str("Krakow John Paul II (KRK) is 11km west, and the train to the main station is 20 minutes for about 12 zloty; a taxi is 70-90 zloty.")), (py_str("budapest"), py_str("Budapest Ferenc Liszt (BUD) is 16km south-east, and bus 100E to Deak Ferenc ter is 30 minutes for about 900 forint; a taxi is about 10,000 forint.")), (py_str("venice"), py_str("Venice has two: Marco Polo (VCE) for most flights, 13km north, and Treviso (TSF) for budget ones, 40km away. From Marco Polo the ATVO bus to Piazzale Roma is 20 minutes and €10.")), (py_str("athens"), py_str("Athens (ATH) is 20km east, and metro line 3 to Syntagma is 40 minutes and €9; a taxi is €40.")), (py_str("copenhagen"), py_str("Copenhagen (CPH) is 8km south-east, and the metro to Kongens Nytorv is 15 minutes for about 30 kroner.")), (py_str("florence"), py_str("Florence (FLR) is 5km north-west and small, and the T2 tram to Santa Maria Novella is 20 minutes for €1.50; a taxi is about €25.")), (py_str("seville"), py_str("Seville (SVQ) is 10km north-east, and the EA bus to the centre is 35 minutes for €4; there is no train link.")), (py_str("london"), py_str("London City (LCY) is the closest to the centre: about 25 minutes to Bank on the DLR. London has five, though, and which one suits depends where you are going: Heathrow (LHR) for most long-haul, Gatwick (LGW) for charters and short-haul, City itself if you are staying in the east. From Heathrow the Piccadilly line is an hour and about £5-6.")), (py_str("rome"), py_str("Rome has two: Fiumicino (FCO), the main one, 30km south-west, and Ciampino (CIA) for budget flights, 15km east. From Fiumicino the Leonardo Express is 32 minutes to Termini for €14.")), (py_str("lisbon"), py_str("Lisbon Humberto Delgado (LIS) is 7km north of the centre, and the red metro line takes 20 minutes for about €2 with a Viva card.")), (py_str("porto"), py_str("Porto Francisco Sa Carneiro (OPO) is 11km north-west, and the metro line E to the centre takes about 30 minutes for €2; a taxi is €25-30.")), (py_str("paris"), py_str("Paris has two: Charles de Gaulle (CDG) for most long-haul, 25km north-east, and Orly (ORY) to the south for domestic and short-haul. The RER B from CDG is 35 minutes and about €11.80.")), (py_str("barcelona"), py_str("Barcelona El Prat (BCN) is 12km south-west, and the Aerobus to Plaza Catalunya is 35 minutes and about €7.50.")), (py_str("madrid"), py_str("Madrid-Barajas (MAD) is 12km north-east, and the metro line 8 into the centre is about €5 and 40 minutes; a taxi is a flat €33.")), (py_str("amsterdam"), py_str("Amsterdam Schiphol (AMS) is 15km south-west, and the train to Centraal is 15-20 minutes for about €6.")), (py_str("dublin"), py_str("Dublin (DUB) is 10km north, and the Aircoach or the 747 bus to the centre is about €7-10 and 30-45 minutes; there is no train link yet.")), (py_str("edinburgh"), py_str("Edinburgh (EDI) is 13km west, and the tram or the 100 bus to the centre takes about 30 minutes for £6.50.")), (py_str("new york"), py_str("New York has three: JFK for most international flights, Newark (EWR) for many too, and LaGuardia (LGA) for domestic. From JFK the AirTrain plus the subway is about $10 and 60-75 minutes.")), (py_str("berlin"), py_str("Berlin Brandenburg (BER) is 25km south-east, and the FEX or S9 train to Hauptbahnhof is 30 minutes for about €4.40.")), (py_str("prague"), py_str("Prague Vaclav Havel (PRG) is 15km west, and bus 119 to the metro, or the Airport Express to the main station, is about €1.50-2.50.")), (py_str("istanbul"), py_str("Istanbul has two: IST on the European side, the main one, and SAW on the Asian side for budget flights. From IST the metro or the Havaist bus is 40-60 minutes.")), (py_str("milan"), py_str("For Milan it is Malpensa (MXP) for long-haul, 50km north-west, or Linate (LIN) for short-haul, 7km east. The Malpensa Express to the centre is 50 minutes.")), (py_str("dubai"), py_str("Dubai International (DXB) is 5km from the centre, and the metro red line reaches most of the city for a few dirhams.")), (py_str("vienna"), py_str("Vienna (VIE) is 18km south-east, and the S-Bahn S7 to Wien Mitte is 25 minutes for about €4.60; the City Airport Train is 16 minutes and €14.90. A taxi is a flat €40.")), (py_str("stockholm"), py_str("Stockholm Arlanda (ARN) is 40km north, and the Arlanda Express is 20 minutes and about 320 kronor; the commuter train takes 40 minutes and costs less. Bromma (BMA) is close to the city but only for domestic flights.")), (py_str("tokyo"), py_str("Tokyo has two: Haneda (HND), 20km south and the convenient one, and Narita (NRT), 60km east, which most long-haul flights use. From Haneda the monorail to Hamamatsucho is 20 minutes for about 500 yen.")), (py_str("brussels"), py_str("Brussels (BRU) is 12km north-east, and the train to the central station is 20 minutes for about €11. Charleroi (CRL) is the budget airport, 60km south, and the bus into town takes an hour.")), (py_str("munich"), py_str("Munich (MUC) is 38km north-east, and the S-Bahn S1 or S8 to the centre is 40 minutes for about €13; a taxi is €70 or more.")), (py_str("zurich"), py_str("Zurich (ZRH) is 12km north, and the train to the main station is 10 to 12 minutes for about 7 francs, which is the easiest airport transfer in Europe.")), (py_str("oslo"), py_str("Oslo Gardermoen (OSL) is 47km north, and the Flytoget is 20 minutes for about 240 kroner; the Vy regional train is slower and about half the price.")), (py_str("helsinki"), py_str("Helsinki-Vantaa (HEL) is 20km north, and the I or P train to the central station is 30 minutes for about €4.10.")), (py_str("tallinn"), py_str("Tallinn (TLL) is 4km from the centre, so it is a tram or a short taxi rather than a transfer: tram 4 gets you in for the price of a city ticket.")), (py_str("reykjavik"), py_str("Keflavik (KEF) is the airport people mean, 50km south-west, and the Flybus to the city is 45 minutes for about 3,500 kroner. Reykjavik (RKV) is a small city airport for domestic flights only.")), (py_str("boston"), py_str("Boston Logan (BOS) is 6km east, and the Silver Line SL1 bus from the terminals takes about 20 minutes for a normal subway fare; the water taxi across the harbour is the fun way in.")), (py_str("san francisco"), py_str("San Francisco (SFO) is 21km south, and BART to the city is 30 minutes for about $10. Oakland (OAK) is across the bay and often cheaper.")), (py_str("los angeles"), py_str("Los Angeles (LAX) is 30km south-west and the one people mean; the FlyAway bus to Union Station is about 45 minutes. Hollywood Burbank (BUR) is closer for domestic flights.")), (py_str("chicago"), py_str("Chicago O'Hare (ORD) is 27km north-west, and the CTA Blue Line runs all night, 45 minutes for $5. Midway (MDW) is nearer the city and on the Orange Line.")), (py_str("toronto"), py_str("Toronto Pearson (YYZ) is 27km north-west, and the UP Express to Union station is 25 minutes for about 12 Canadian dollars.")), (py_str("sydney"), py_str("Sydney (SYD) is 8km south, and the Airport Link train to Central is 13 minutes for about 20 Australian dollars; a taxi is 25 to 35.")), (py_str("singapore"), py_str("Singapore Changi (SIN) is 20km east, and the MRT to the city is 30 to 40 minutes for about S$2. Allow an hour there before your flight: the Jewel waterfall is inside the airport.")), (py_str("bangkok"), py_str("Bangkok has two: Suvarnabhumi (BKK), the main one 30km east, and Don Mueang (DMK), 25km north, for budget flights. From Suvarnabhumi the Airport Rail Link is 30 minutes for 45 baht.")), (py_str("hanoi"), py_str("Hanoi (HAN) is 35km north, and bus 86 to the old quarter is 45 minutes for 35,000 dong; a taxi or a Grab is about 350,000 dong and 40 minutes.")), (py_str("cape town"), py_str("Cape Town (CPT) is 20km east, and a taxi or an Uber to the centre is 20 to 30 minutes and about 250 rand. There is a train, but not one to take with bags.")), (py_str("mexico city"), py_str("Mexico City (MEX) is 13km east, and the metro line 5 is cheap and slow; a taxi from the official stand inside the terminal is 30 to 45 minutes and about 250 pesos.")), (py_str("havana"), py_str("Havana (HAV) is 15km south of the city, and a taxi to the old town is 25 to 30 minutes and about 25 dollars or the same in euros; the airport bus is not worth the wait.")), (py_str("buenos aires"), py_str("Buenos Aires has two: Ezeiza (EZE), 30km south, for long-haul, and Aeroparque (AEP) in the city for domestic flights. From Ezeiza a taxi is 45 minutes and about 30 dollars; bus 8 is the cheap way.")), (py_str("rio de janeiro"), py_str("Rio has two: Galeao (GIG), 20km north, for international flights, and Santos Dumont (SDU) in the city for the Sao Paulo shuttle. From Galeao a taxi is 30 to 50 minutes.")), (py_str("naples"), py_str("Naples (NAP) is 6km north-east, and the Alibus to the central station and the port is 20 minutes for €5; a taxi is about €25, and agree the price first.")), (py_str("valencia"), py_str("Valencia (VLC) is 9km west, and metro line 3 or 5 to the centre is 20 minutes for about €5.")), (py_str("granada"), py_str("Granada (GRX) is 17km west and small, and the airport bus to the centre is 40 minutes for €3. Most people fly to Malaga instead and take the bus, which is two hours.")), (py_str("santorini"), py_str("Santorini (JTR) is 6km from Fira, and the bus meets the flights; a taxi is 20 to 30 euros. It is a small airport with a short runway, so summer flights are often delayed.")), (py_str("san sebastian"), py_str("San Sebastian (EAS) is 20km east at Hondarribia and has very few flights, so most people fly to Bilbao (75 minutes by bus) or Biarritz (40 minutes).")), (py_str("ljubljana"), py_str("Ljubljana (LJU) is 25km north, and the airport bus to the centre is 30 minutes for about €4; a taxi is €25 to €30.")), (py_str("kyoto"), py_str("Kyoto has no airport of its own: fly into Osaka Kansai (KIX), which is 75 minutes away on the Haruka train, or into Tokyo and take the shinkansen.")), (py_str("bath"), py_str("Bath has no airport: Bristol (BRS) is 30km west, and the Flyer bus runs to Bath in 55 minutes. By train, come into Bath Spa from Bristol Temple Meads."))]) }
