    fn __data67() -> Py { py_dict(vec![(py_str("spain"), py_str("Tapas at the bar - two or three plates between you - paella in Valencia and pintxos in San Sebastián. Jamón and pimientos de Padrón are the cheap way in.")), (py_str("italy"), py_str("Rome for cacio e pepe or carbonara, Naples for pizza and Bologna for ragù, with a coffee standing at the bar. Order the house wine; it is cheaper than water in some places.")), (py_str("france"), py_str("A bakery lunch, steak-frites in Paris and a bouchon in Lyon, with cider and cream in Normandy. The fixed-price lunch menu is where the value is.")), (py_str("portugal"), py_str("Pastéis de nata and grilled sardines in Lisbon, a francesinha in Porto and cataplana on the Algarve. Look for the prato do dia, a set lunch with wine for very little.")), (py_str("greece"), py_str("Souvlaki, grilled octopus and a proper village salad: tomato, cucumber, onion and a slab of feta, no lettuce. Eat where the menu is short and the bread is fresh.")), (py_str("turkey"), py_str("Balık ekmek - fish in bread - by the water in Istanbul, a breakfast of cheese, olives and menemen, and pistachio baklava in the south-east.")), (py_str("morocco"), py_str("Tagine, couscous on a Friday and mint tea poured from a height, with the evening food stalls in Marrakech the easy start. Bread and olives come with everything.")), (py_str("egypt"), py_str("Koshari from a street shop - rice, lentils and pasta with tomato sauce - ful medames for breakfast, and grilled fish by the Red Sea.")), (py_str("japan"), py_str("Sushi at a counter and a bowl of ramen in Tokyo, takoyaki and okonomiyaki in Osaka, tofu and kaiseki in Kyoto. Convenience-store food is genuinely good and cheap.")), (py_str("thailand"), py_str("Street food is the point: pad thai, som tam and moo ping, cooked in front of you where it is busy. Say \"not spicy\" clearly, and eat breakfast at the market.")), (py_str("india"), py_str("Dosa, idli and coconut curries in the south; butter chicken, chaat and tandoori bread in the north. Breakfast is the meal to try first.")), (py_str("mexico"), py_str("Tacos al pastor from a stand, tamales for breakfast and mole in Oaxaca, with the salsa on the side so you choose the heat.")), (py_str("croatia"), py_str("Grilled fish and black risotto on the coast, ćevapi inland, and a konoba with a short menu is the best bet. Pizza is everywhere and usually good.")), (py_str("germany"), py_str("Bratwurst from a stand, a proper schnitzel and rye bread with everything; in Bavaria a pretzel and a cold beer counts as lunch.")), (py_str("netherlands"), py_str("Bitterballen with a beer, raw herring with onions from a stall, and a stroopwafel warm off the iron.")), (py_str("ireland"), py_str("Fish and chips, a full Irish breakfast, and brown bread with smoked salmon; chowder on the west coast.")), (py_str("scotland"), py_str("Fish and chips, a full Scottish breakfast, haggis with neeps and tatties, and seafood in Oban or on the west coast.")), (py_str("england"), py_str("Fish and chips, a Sunday roast and a proper curry house; in London the markets are better eating than the streets around the sights.")), (py_str("iceland"), py_str("Lamb soup, skyr and a hot dog with everything from the stand in Reykjavík, with fish straight off the boat. It is expensive, so eat one good meal a day.")), (py_str("poland"), py_str("Pierogi, a bowl of żurek sour rye soup and kielbasa off a grill, with pierogi shops the cheapest full meal in town.")), (py_str("vietnam"), py_str("Phở for breakfast in Hanoi, bánh mì from a cart and fresh spring rolls down the middle of the country. Eat where the stools are small and the queue is long.")), (py_str("china"), py_str("Go regional: dim sum in Guangzhou and Hong Kong, hand-pulled noodles in Xi'an and a Sichuan hotpot in Chengdu. Order several dishes and share them.")), (py_str("belgium"), py_str("Mussels with chips, a waffle from a stall and frites with mayonnaise; the beer is the point, and every bar has its own glass.")), (py_str("austria"), py_str("Wiener schnitzel, a sausage from a stand and a slice of Sachertorte, with coffee and cake an entire afternoon.")), (py_str("tunisia"), py_str("Couscous on a Friday, a brik with an egg inside and harissa with everything, usually with bread and olives first.")), (py_str("cuba"), py_str("Ropa vieja, black beans with rice and a strong coffee; the paladares - private restaurants - beat the state ones.")), (py_str("canada"), py_str("Poutine in Quebec, salmon on the west coast and a proper diner breakfast; portions are big, so order less than you think.")), (py_str("australia"), py_str("Fish and chips on the coast, a meat pie and a flat white; the coffee is what people miss when they leave.")), (py_str("usa"), py_str("Go regional: barbecue in Texas or Kansas City, a po'boy in New Orleans, pizza by the slice in New York, tacos in Los Angeles.")), (py_str("argentina"), py_str("Beef is the point: a parrilla grilled over coals with chimichurri, empanadas from a bakery and a mate to carry round. Order the bife de chorizo and share it, and eat late: nowhere is busy before nine.")), (py_str("brazil"), py_str("A kilo restaurant at lunch, where you pay by weight, is the cheap way in; feijoada on a Saturday, pão de queijo and açaí from a corner shop, and churrasco for a proper dinner.")), (py_str("peru"), py_str("Ceviche at lunch, never in the evening, with leche de tigre on the side; lomo saltado and a quinoa soup in the Andes. Lima is worth a whole day of eating.")), (py_str("south korea"), py_str("Barbecue you cook at the table, with lettuce leaves and a dozen little dishes that come free; then fried chicken with beer, and street stalls for tteokbokki and hotteok.")), (py_str("lebanon"), py_str("Mezze is the meal: hummus, tabbouleh, fattoush and grilled halloumi, then kibbeh and a plate of mixed grill. Order several small plates and share.")), (py_str("israel"), py_str("Hummus with a runny egg for breakfast, sabich and falafel in pita, and a market lunch of cheeses, olives and bread. Salads come with everything.")), (py_str("nigeria"), py_str("Jollof rice with fried plantain, a bowl of egusi with pounded yam and suya off a night grill. Eat where the queue is local and the pepper is not toned down.")), (py_str("kenya"), py_str("Nyama choma - grilled goat or beef - with kachumbari, plus ugali and sukuma wiki; in Mombasa the coast gives you biryani and coconut curries.")), (py_str("south africa"), py_str("A braai is the meal: grilled meat, a pap and relish on the side. Then bunny chow in Durban, biltong from a butcher and a bobotie.")), (py_str("wales"), py_str("Cawl, the lamb and leek broth, with bread and cheese; Welsh rarebit on toast, laverbread for breakfast in the valleys, and Welsh cakes warm from the griddle.")), (py_str("new zealand"), py_str("A meat pie from a dairy, fish and chips on the beach and a hāngi if you get invited; lamb is the dinner and the flat white is the coffee.")), (py_str("sweden"), py_str("Meatballs with lingonberry, pickled herring at midsummer and a kanelbulle with coffee; lunch is often a buffet table of salads and bread.")), (py_str("denmark"), py_str("Smørrebrød - open sandwiches - for lunch, a hot dog from a stand and pastry from a proper bakery. New Nordic tasting menus cost a lot; the bakeries do not.")), (py_str("norway"), py_str("Salmon and cod, a brown cheese on toast for breakfast and a waffle with jam; eating out is very expensive, so the supermarket deli counter is how people lunch.")), (py_str("switzerland"), py_str("Fondue and raclette, rösti with a fried egg and a plate of bündner fleisch; the supermarkets and bakery lunch are the only cheap meals.")), (py_str("russia"), py_str("Borscht with sour cream, pelmeni with butter and a blini from a street kiosk; a stolovaya canteen is cheap and filling, and the tea comes with everything.")), (py_str("singapore"), py_str("A hawker centre is the answer: chicken rice, laksa and char kway teow from different stalls, all cheap. Order with tissue packets on the table to claim a seat.")), (py_str("malaysia"), py_str("Nasi lemak for breakfast, char kway teow and laksa from the hawkers, and roti canai at any hour; the food courts are where the good cheap eating is.")), (py_str("indonesia"), py_str("Nasi goreng and satay from a warung, rendang in Padang and gado-gado; eat where the warung is busy and the price list is on the wall.")), (py_str("philippines"), py_str("Lechon for a celebration, adobo and sinigang at home, and halo-halo in the heat; the malls have the air conditioning and the food halls.")), (py_str("pakistan"), py_str("Nihari and haleem for breakfast in Lahore, chaat from a stall and a plate of biryani at lunch; the grill houses do seekh kebab and naan fresh from the tandoor.")), (py_str("sri lanka"), py_str("Rice and curry, several dishes at once, with hoppers for breakfast and kottu off a hotplate at night; the fish curry on the coast is the one to order."))]) }
